#include "tigersheets/ooxml.hpp"
#include <filesystem>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <unistd.h>
#include <zip.h>
#include <pugixml.hpp>
using namespace tigersheets;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void member(const std::string& path,const std::string& name,const std::string& bytes){int error=0;auto* archive=zip_open(path.c_str(),0,&error);require(archive,"open fixture ZIP");auto* source=zip_source_buffer(archive,bytes.data(),bytes.size(),0);require(source&&zip_file_add(archive,name.c_str(),source,ZIP_FL_OVERWRITE)>=0,"write fixture ZIP member");require(zip_close(archive)==0,"close fixture ZIP");}
std::string xml(const pugi::xml_document& document){std::ostringstream output;document.save(output);return output.str();}
bool changedPart(const std::filesystem::path& directory,const std::string& kind){
 auto book=WorkbookSession().snapshot();book["sheets"][0]["cells"]=Json::array({{{"row",1},{"col",1},{"input","Base"}},{{"row",2},{"col",1},{"input","100"},{"style",{{"numberFormat","0.00"}}}}});const auto sourcePath=(directory/(kind+"-source.xlsx")).string();writeWorkbook(sourcePath,book);auto source=readWorkbook(sourcePath);
 pugi::xml_document sheet;require(sheet.load_string(source.entries.at("xl/worksheets/sheet1.xml").c_str()),"source worksheet XML");auto a1=sheet.child("worksheet").child("sheetData").child("row").child("c");a1.attribute("t").set_value("s");a1.remove_children();a1.append_child("v").text().set("0");member(sourcePath,"xl/worksheets/sheet1.xml",xml(sheet));member(sourcePath,"xl/sharedStrings.xml",R"(<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="1" uniqueCount="1"><si><t>Base</t></si></sst>)");
 pugi::xml_document relationships;require(relationships.load_string(source.entries.at("xl/_rels/workbook.xml.rels").c_str()),"source relationships XML");auto relationship=relationships.document_element().append_child("Relationship");relationship.append_attribute("Id")="rSharedStrings";relationship.append_attribute("Type")="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings";relationship.append_attribute("Target")="sharedStrings.xml";member(sourcePath,"xl/_rels/workbook.xml.rels",xml(relationships));
 pugi::xml_document types;require(types.load_string(source.entries.at("[Content_Types].xml").c_str()),"source content types XML");auto type=types.document_element().append_child("Override");type.append_attribute("PartName")="/xl/sharedStrings.xml";type.append_attribute("ContentType")="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml";member(sourcePath,"[Content_Types].xml",xml(types));
 source=readWorkbook(sourcePath);auto managed=source.workbook;managed["financialModels"]=Json::array({{{"id","base"},{"version",1},{"name","Base assumptions"},{"kind","assumption_set"},{"cells",Json::array({{{"sheet","sheet-1"},{"row",1},{"col",1},{"type","string"},{"value","Base"}},{{"sheet","sheet-1"},{"row",2},{"col",1},{"type","number"},{"value",100}}})}}});const auto managedPath=(directory/(kind+"-managed.xlsx")).string();writeWorkbook(managedPath,managed,&source);const auto before=readWorkbook(managedPath);require(before.workbook.contains("financialModels"),"unaltered native source restores saved financial definitions");
 if(kind=="sharedStrings"){pugi::xml_document strings;require(strings.load_string(before.entries.at("xl/sharedStrings.xml").c_str()),"managed shared strings XML");strings.child("sst").child("si").child("t").text().set("Changed");member(managedPath,"xl/sharedStrings.xml",xml(strings));}
 else{pugi::xml_document styles;require(styles.load_string(before.entries.at("xl/styles.xml").c_str()),"managed styles XML");for(auto format:styles.child("styleSheet").child("numFmts").children("numFmt"))if(std::string(format.attribute("formatCode").value())=="0.00")format.attribute("formatCode").set_value("0%");member(managedPath,"xl/styles.xml",xml(styles));}
 const auto after=readWorkbook(managedPath);require(after.entries.at("xl/worksheets/sheet1.xml")==before.entries.at("xl/worksheets/sheet1.xml"),"authority probe changes no worksheet XML bytes");if(kind=="sharedStrings")require(after.workbook.at("sheets")[0].at("cells")[0].at("input")=="Changed","native shared-string edit remains authoritative");else require(after.workbook.at("sheets")[0].at("cells")[1].at("style").at("numberFormat")=="0%","native style-only edit remains authoritative");const bool ignored=!after.workbook.contains("financialModels");if(!ignored)std::cerr<<kind<<"-only native edit retained stale private financial definitions\n";return ignored;
}
}
int main(){try{char pattern[]="/tmp/tigersheets-financial-authority-XXXXXX";const auto* created=mkdtemp(pattern);require(created,"private fixture directory");const std::filesystem::path directory(created);const auto strings=changedPart(directory,"sharedStrings"),styles=changedPart(directory,"styles");std::filesystem::remove_all(directory);require(strings&&styles,"native shared strings and styles must invalidate saved financial metadata without worksheet rewrites");std::cout<<"financial metadata authority tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
